select #{item.uuid,jdbcType=VARCHAR} uuid, #{item.counterId,jdbcType=VARCHAR} counterId, #{item.counterType,jdbcType=VARCHAR} counterType, #{item.counterName,jdbcType=VARCHAR} counterName, #{item.linkId,jdbcType=VARCHAR} linkId, #{item.managerId,jdbcType=VARCHAR} managerId, #{item.headBank,jdbcType=VARCHAR} headBank, #{item.contact,jdbcType=VARCHAR} contact, #{item.contactWay,jdbcType=VARCHAR} contactWay, #{item.remark,jdbcType=VARCHAR} remark, #{item.createUser,jdbcType=VARCHAR} createUser, #{item.createDept,jdbcType=VARCHAR} createDept, #{item.createTime,jdbcType=TIMESTAMP} createTime, #{item.updateUser,jdbcType=VARCHAR} updateUser, #{item.updateTime,jdbcType=TIMESTAMP} updateTime, #{item.counterType1,jdbcType=VARCHAR} counterType1, #{item.counterType2,jdbcType=VARCHAR} counterType2, #{item.isCentralCounter,jdbcType=VARCHAR} isCentralCounter from dual
) TEMP where not exists (select 1 from CHB_MST_COUNTER_PARTY CII 过滤条件) ) de ;
UPDATE CHB_MST_COUNTER_PARTY as A, ( select COUNTER_TYPE,COUNTER_NAME,LINK_ID, MANAGER_ID,HEAD_BANK,CONTACT,CONTACT_WAY, REMARK, UPDATE_TIME,a.COUNTER_TYPE1, UPDATE_USER,COUNTER_TYPE2,IS_CENTRAL_COUNTER, STATUS from ( select TEMP.* from (
select #{item.uuid,jdbcType=VARCHAR} uuid, #{item.counterId,jdbcType=VARCHAR} counterId, #{item.counterType,jdbcType=VARCHAR} counterType, #{item.counterName,jdbcType=VARCHAR} counterName, #{item.linkId,jdbcType=VARCHAR} linkId, #{item.managerId,jdbcType=VARCHAR} managerId, #{item.headBank,jdbcType=VARCHAR} headBank, #{item.contact,jdbcType=VARCHAR} contact, #{item.contactWay,jdbcType=VARCHAR} contactWay, #{item.remark,jdbcType=VARCHAR} remark, #{item.createUser,jdbcType=VARCHAR} createUser, #{item.createDept,jdbcType=VARCHAR} createDept, #{item.createTime,jdbcType=TIMESTAMP} createTime, #{item.updateUser,jdbcType=VARCHAR} updateUser, #{item.updateTime,jdbcType=TIMESTAMP} updateTime, #{item.counterType1,jdbcType=VARCHAR} counterType1, #{item.counterType2,jdbcType=VARCHAR} counterType2, #{item.isCentralCounter,jdbcType=VARCHAR} isCentralCounter from dual
) TEMP ) de ) AS B set A.* = B.* where exists (select 1 from CHB_MST_COUNTER_PARTY CII where CII.COUNTER_ID = TEMP.counterId and CII.STATUS != 'D');
